  ('1108 Series Flat Pattern Bracket (1-1)', '1108-0001-0001', null, 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-1-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/197/images/1281/1108-0001-0001__84888__74686.1701991229.386.513.jpg?c=1', 'STRUCTURE / Brackets / Aluminum Flat Brackets', 'gobilda'),
  ('1108 Series Flat Pattern Bracket (1-2)', '1108-0001-0002', 'Easily add a 14mm hole to your structure using this pattern bracket. The distance between the 14mm hole at the square end, and the one(25) at the rounded end is 48mm so you can use this to properly space gears and drive components from one(26) another.', 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-1-2/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1077/images/5294/1108-0001-0002__67792__76888.1701992489.386.513.jpg?c=1', 'STRUCTURE / Brackets / Aluminum Flat Brackets', 'gobilda'),
  ('1108 Series Flat Pattern Bracket (2-1)', '1108-0002-0001', null, 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-2-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/199/images/1307/1108-0002-0001-Patent-Pending__50058__67507.1701991236.386.513.jpg?c=1', 'STRUCTURE / Brackets / Steel Flat Brackets', 'gobilda'),
  ('1108 Series Flat Pattern Bracket (2-2)', '1108-0002-0002', 'This flat pattern bracket allows you to create a 135 degree angle between two plates or pieces of channel. The five holes at each end are spaced 8mm apart so they will align with any grid-based part.', 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-2-2/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1080/images/5304/1108-0002-0002_PatentsPending__58026__14858.1701992492.386.513.jpg?c=1', 'STRUCTURE / Brackets / Aluminum Flat Brackets', 'gobilda'),
  ('1108 Series Flat Pattern Bracket (2-3)', '1108-0002-0003', 'This flat pattern bracket works well for creating a 135 degree angle between two structural pieces. The 40mm width allows the bracket to slide down inside of channel without contacting the walls.', 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-2-3/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1072/images/5282/1108-0002-0003_PatentsPending__51441__81640.1701992485.386.513.jpg?c=1', 'STRUCTURE / Brackets / Aluminum Flat Brackets', 'gobilda'),
  ('1108 Series Flat Pattern Bracket (3-1)', '1108-0003-0001', 'The 1108-0003-0001 is symmetrical on all four sides and provides a central point to build off of.', 'goBILDA', null, true, 'https://www.gobilda.com/1108-series-flat-pattern-bracket-3-1/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1076/images/5286/1108-0003-0001_PatentsPending__13001__87890.1701992487.386.513.jpg?c=1', 'STRUCTURE / Brackets / Aluminum Flat Brackets', 'gobilda'),
